using System;using System.Linq;using System.Reflection;using WorldGenesis.Simulation;
#if UNITY_5_3_OR_NEWER
using NUnit.Framework;using UnityEngine;
#endif
namespace WorldGenesis.Tests {
 public static class FaunaBalanceScenarios {
  public static Func<WorldState,WorldState> Clone;public static Func<WorldState,string> Snapshot;
  internal static void Need(bool ok,string reason){if(!ok)throw new InvalidOperationException(reason);}
  internal static object Call(SimulationEngine e,string name,params object[] args){return typeof(SimulationEngine).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(e,args);}
  internal static SimulationEngine Flat(){var w=new WorldState{Width=48,Height=48,Seed=717,RngState=717,Cells=new TileData[48*48],NaturalWildlife=false};for(int i=0;i<w.Cells.Length;i++)w.Cells[i]=new TileData{Terrain=TerrainType.Grass,Height=.5f,RouteHeight=.5f,Vegetation=.8f,Moisture=.6f,Temperature=.5f,DrainageParent=-1};var e=new SimulationEngine(w);w.Weather.Automatic=false;return e;}
  internal static void Valid(SimulationEngine e){Need(e.World.Validate(out string error),error);}
  static UnitData[] Pair(SimulationEngine e,int females=1){e.Spawn(SpeciesType.Goat,20,20,females+1);var a=e.World.Units.ToArray();for(int i=0;i<a.Length;i++){a[i].X=a[i].Y=20.5f;a[i].Sex=i==0?Sex.Male:Sex.Female;a[i].Age=4;a[i].Hunger=.1f;a[i].Health=a[i].MaxHealth;a[i].Task=UnitTask.Idle;a[i].DecisionTimer=100000;a[i].NextBreedingTick=0;a[i].BreedingSeconds=WildlifeCatalog.BreedingInterval(a[i].Species,false);}return a;}
  public static void OneMaleCannotProduceAnInstantLitterAndBothParentsWait(){var e=Flat();var a=Pair(e,2);Call(e,"UpdateWildlife");Need(e.World.Units.Count==4&&e.World.WildlifeBirths==1,"one pair must produce one offspring");Need(a[0].NextBreedingTick==e.World.Tick+3600&&a[1].NextBreedingTick>e.World.Tick,"both parental cooldowns");for(int i=0;i<120;i++){e.World.Tick+=10;Call(e,"UpdateWildlife");}Need(e.World.Units.Count==4,"male reused during cooldown");Valid(e);}
  public static void ReproductionNeedsHealthyReachablePairAndBirthLaw(){var e=Flat();var a=Pair(e);e.World.Laws.Births=false;Call(e,"UpdateWildlife");Need(e.World.Units.Count==2,"law ignored");e.World.Laws.Births=true;a[0].Hunger=.8f;Call(e,"UpdateWildlife");Need(e.World.Units.Count==2,"starving father");a[0].Hunger=.1f;a[0].X=23.5f;for(int y=0;y<48;y++){var t=e.World.Cells[e.World.Index(22,y)];t.Terrain=TerrainType.Mountain;e.World.Cells[e.World.Index(22,y)]=t;}e.World.NavigationRevision++;Call(e,"UpdateWildlife");Need(e.World.Units.Count==2,"pair through wall");a[0].X=20.5f;Call(e,"UpdateWildlife");Need(e.World.Units.Count==3,"healthy pair failed");Valid(e);}
  public static void BarrenHabitatBlocksBirthAndRestorationConsumesActualForage(){var e=Flat();Pair(e);for(int i=0;i<e.World.Cells.Length;i++)e.World.Cells[i].Vegetation=0;Call(e,"RefreshWildlifeHabitat");Call(e,"UpdateWildlife");Need(e.World.Units.Count==2&&e.World.WildlifeHabitatCapacity==0,"barren land birth");for(int i=0;i<e.World.Cells.Length;i++)e.World.Cells[i].Vegetation=.8f;Call(e,"RefreshWildlifeHabitat");double forage=e.World.Cells.Sum(t=>(double)t.Vegetation);Call(e,"UpdateWildlife");Need(e.World.Units.Count==3&&Math.Abs(forage-e.World.Cells.Sum(t=>(double)t.Vegetation)-.5)<.001,"birth did not consume local forage");Valid(e);}
  public static void HabitatContractionAndExplicitOverpopulationNeverDeleteLivingAnimals(){var e=Flat();e.Spawn(SpeciesType.Sheep,20,20,90);int[] ids=e.World.Units.Select(u=>u.Id).ToArray();for(int i=0;i<e.World.Cells.Length;i++)e.World.Cells[i].Vegetation=0;Call(e,"RefreshWildlifeHabitat");Call(e,"UpdateWildlife");Need(e.World.Units.Count==90&&ids.SequenceEqual(e.World.Units.Select(u=>u.Id))&&e.World.Units.All(u=>u.Health==u.MaxHealth),"cap culled living population");Valid(e);}
  public static void DomesticPairConsumesRealFeedAndSharesCooldown(){var e=Flat();e.Spawn(SpeciesType.Human,10,10,2);SettlementData town=e.World.Settlements[0];BuildingData p=(BuildingData)Call(e,"AddBuilding",town,20,20,BuildingType.Pasture);e.Spawn(SpeciesType.Goat,20,20,3);var animals=e.World.Units.Where(u=>WildlifeCatalog.IsAnimal(u.Species)).ToArray();for(int i=0;i<animals.Length;i++){var a=animals[i];a.IsDomestic=true;a.PastureId=p.Id;a.AnimalOwnerId=town.Id;a.X=a.Y=20.5f;a.Age=4;a.Sex=i==0?Sex.Male:Sex.Female;a.Hunger=.1f;a.BreedingSeconds=WildlifeCatalog.BreedingInterval(a.Species,true);a.NextBreedingTick=0;}int initial=e.World.Units.Count;Call(e,"UpdateDomesticAnimals");Need(e.World.Units.Count==initial,"unfed birth");p.AgriculturalStock[(int)AgriculturalProduct.Hay]=4;Call(e,"UpdateDomesticAnimals");Need(e.World.Units.Count==initial+1&&p.AgriculturalStock[(int)AgriculturalProduct.Hay]==2&&e.World.DomesticAnimalBirths==1,"pair/feed accounting");Call(e,"UpdateDomesticAnimals");Need(e.World.Units.Count==initial+1,"same male repeated litter");Valid(e);}
  public static void WildlifeVersionOneMigrationPreservesLivesCargoAndRng(){var e=Flat();var pair=Pair(e);var w=Clone(e.World);w.WildlifeVersion=1;foreach(var a in w.Units){a.BreedingSeconds=89;a.NextBreedingTick=0;}uint rng=w.RngState;int id=w.NextId;float health=w.Units.Sum(u=>u.Health);var migrated=new SimulationEngine(w);Need(w.WildlifeVersion==2&&w.RngState==rng&&w.NextId==id&&w.Units.Sum(u=>u.Health)==health&&w.Units.Count==2,"migration altered living world");Need(w.Units.All(u=>u.NextBreedingTick>w.Tick),"migration birth burst");string first=Snapshot(w);new SimulationEngine(w);Need(first==Snapshot(w),"migration not idempotent");Valid(migrated);}
  public static void CooldownAndEcologySaveContinueExactly(){var first=Flat();Pair(first);Call(first,"UpdateWildlife");for(int i=0;i<233;i++)first.Step(.1f);var second=new SimulationEngine(Clone(first.World));for(int i=0;i<1200;i++){first.Step(.1f);second.Step(.1f);}Need(Snapshot(first.World)==Snapshot(second.World),"save changed ecology continuation");Valid(first);}
  public static void NaturalImmigrationWaitsAndNeverPopulatesBarrenWorld(){var e=Flat();e.World.NaturalWildlife=true;for(int i=0;i<e.World.Cells.Length;i++)e.World.Cells[i].Terrain=TerrainType.Forest;e.World.Tick=200;Call(e,"UpdateWildlife");int n=e.World.Units.Count;Need(n>0&&n<=2,"initial group");long next=e.World.NextWildlifeSpawnTick;Need(next-e.World.Tick==1200,"immigration interval");e.World.Tick=next-10;Call(e,"UpdateWildlife");Need(e.World.WildlifeImmigrations==n,"immigration before cooldown");for(int i=0;i<e.World.Cells.Length;i++)e.World.Cells[i].Vegetation=0;e.World.Tick=next;Call(e,"RefreshWildlifeHabitat");Call(e,"UpdateWildlife");Need(e.World.WildlifeImmigrations==n,"barren immigration");Valid(e);}
  public static void CompetingPairsRespectLastWorldSlotsWithoutDeletingExistingPopulation(){var e=Flat();e.Spawn(SpeciesType.Goat,20,20,6);for(int i=0;i<6;i++){var a=e.World.Units[i];a.X=a.Y=20.5f;a.Age=4;a.Sex=i<3?Sex.Male:Sex.Female;a.Hunger=.1f;a.BreedingSeconds=WildlifeCatalog.BreedingInterval(a.Species,false);a.NextBreedingTick=0;}for(int i=0;i<9992;i++)Call(e,"AddUnit",SpeciesType.Human,35,35,0,false);e.World.WildlifeHabitatCapacity=128;e.World.NextWildlifeHabitatTick=10000;Call(e,"UpdateWildlife");Need(e.World.Units.Count==10000&&e.World.WildlifeBirths==2,"competing pairs overflowed final world slots");Need(e.World.WildlifeDeaths==0,"birth limit culled existing lives");Valid(e);}
  public static void AnimalAgingUsesLongerLifeAndDeathIsCountedOnce(){var e=Flat();e.Spawn(SpeciesType.Goat,20,20,1);UnitData a=e.World.Units[0];float age=a.Age;e.Step(.1f);Need(Math.Abs(a.Age-age-.00125f /* User0.10: future aging is halved for animals too. */)<.00001f,"animal aging rate");a.Health=0;e.Step(.1f);e.Step(.1f);Need(e.World.WildlifeDeaths==1&&e.World.Units.Count==0,"death missing or counted twice");Valid(e);}
 }
#if UNITY_5_3_OR_NEWER
 public class FaunaBalanceTests {
 [SetUp]public void Setup(){FaunaBalanceScenarios.Clone=w=>JsonUtility.FromJson<WorldState>(JsonUtility.ToJson(w));FaunaBalanceScenarios.Snapshot=w=>JsonUtility.ToJson(w);}
 [TestCase("OneMaleCannotProduceAnInstantLitterAndBothParentsWait")][TestCase("ReproductionNeedsHealthyReachablePairAndBirthLaw")][TestCase("BarrenHabitatBlocksBirthAndRestorationConsumesActualForage")][TestCase("HabitatContractionAndExplicitOverpopulationNeverDeleteLivingAnimals")][TestCase("DomesticPairConsumesRealFeedAndSharesCooldown")][TestCase("WildlifeVersionOneMigrationPreservesLivesCargoAndRng")][TestCase("CooldownAndEcologySaveContinueExactly")][TestCase("NaturalImmigrationWaitsAndNeverPopulatesBarrenWorld")][TestCase("AnimalAgingUsesLongerLifeAndDeathIsCountedOnce")][TestCase("CompetingPairsRespectLastWorldSlotsWithoutDeletingExistingPopulation")]
 public void Scenario(string name){typeof(FaunaBalanceScenarios).GetMethod(name).Invoke(null,null);}}
#endif
}
